describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(widget, 2); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500), // new price
    };

    const result = await cart.checkout({ priceFetcher });
    // subtotal = 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service error");
  });

  it("checks inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w", 1);
  });

  it("throws InventoryError when product is unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("discontinued");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider to compute tax", async () => {
    const tax = mockTax(() => 0); // sync tax should be bypassed
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1); // subtotal 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // 1000 * 0.08 = 80
    expect(result.totals.taxCents).toBe(80);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    // sync tax should NOT have been called for this checkout
    expect(tax.computeTaxCents).not.toHaveBeenCalled();
  });

  it("combines priceFetcher + asyncTaxProvider + shipping", async () => {
    const discount = mockDiscount(() => 100);
    const shipping = mockShipping(() => 300);

    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(widget, 1); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
    // subtotal = 2000, discount = 100, discounted = 1900
    // tax = 1900 * 0.10 = 190, shipping = 300
    // total = 1900 + 190 + 300 = 2390
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(190);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(2390);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("inventory check runs after price refresh", async () => {
    const callOrder: string[] = [];
    const cart = new Cart();
    cart.add(widget, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("price");
        return 1000;
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("inventory");
        return { available: true };
      }),
    };

    await cart.checkout({ priceFetcher, inventoryChecker });
    expect(callOrder).toEqual(["price", "inventory"]);
  });

  it("first failing inventory line wins", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should throw");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("g");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects percent=%s", (percent, expectedMsg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(expectedMsg);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 100, 33],
      [10, 1001, 100], // floors: 1001 * 10 / 100 = 100.1 → 100
      [15, 999, 149],  // floors: 999 * 15 / 100 = 149.85 → 149
    ])(
      "%i%% of %i cents = %i cents",
      (percent, subtotal, expected) => {
        const policy = new PercentageDiscountPolicy(percent);
        expect(policy.computeDiscountCents(subtotal)).toBe(expected);
      },
    );

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "non-negative integer"],
      [10.5, "non-negative integer"],
      [NaN, "non-negative integer"],
    ])("rejects amountCents=%s", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns full amount when subtotal exceeds discount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1500);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns 0 when discount amount is 0", () => {
      const policy = new FixedAmountDiscountPolicy(0);
      expect(policy.computeDiscountCents(1000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent policy results against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both computed against 1000: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("sums can exceed subtotal (clamping is Cart's job)", () => {
      const p1 = new PercentageDiscountPolicy(80); // 800
      const p2 = new FixedAmountDiscountPolicy(500); // 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // 800 + 500 = 1300 > 1000 — composite doesn't clamp
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, not negative
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new PercentageDiscountPolicy(10); // 10% of 900 = 90
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step at remaining subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // step1: min(800,1000) = 800, remaining=200
      // step2: min(500,200) = 200, remaining=0
      // total = 800 + 200 = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("order matters in chain mode", () => {
      const big = new PercentageDiscountPolicy(50);
      const small = new FixedAmountDiscountPolicy(100);

      const bigFirst = new CompositeDiscountPolicy([big, small], "chain");
      const smallFirst = new CompositeDiscountPolicy([small, big], "chain");

      // bigFirst: 50% of 1000 = 500, then min(100, 500) = 100 → 600
      // smallFirst: min(100, 1000) = 100, then 50% of 900 = 450 → 550
      expect(bigFirst.computeDiscountCents(1000)).toBe(600);
      expect(smallFirst.computeDiscountCents(1000)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new PercentageDiscountPolicy(50);
      const composite = new CompositeDiscountPolicy([p], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      // sum: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

