describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent policy results against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both computed against 1000: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("sums can exceed subtotal (clamping is Cart's job)", () => {
      const p1 = new PercentageDiscountPolicy(80); // 800
      const p2 = new FixedAmountDiscountPolicy(500); // 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // 800 + 500 = 1300 > 1000 — composite doesn't clamp
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, not negative
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially against remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new PercentageDiscountPolicy(10); // 10% of 900 = 90
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("caps each step at remaining subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(500);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // step1: min(800,1000) = 800, remaining=200
      // step2: min(500,200) = 200, remaining=0
      // total = 800 + 200 = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("order matters in chain mode", () => {
      const big = new PercentageDiscountPolicy(50);
      const small = new FixedAmountDiscountPolicy(100);

      const bigFirst = new CompositeDiscountPolicy([big, small], "chain");
      const smallFirst = new CompositeDiscountPolicy([small, big], "chain");

      // bigFirst: 50% of 1000 = 500, then min(100, 500) = 100 → 600
      // smallFirst: min(100, 1000) = 100, then 50% of 900 = 450 → 550
      expect(bigFirst.computeDiscountCents(1000)).toBe(600);
      expect(smallFirst.computeDiscountCents(1000)).toBe(550);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new PercentageDiscountPolicy(50);
      const composite = new CompositeDiscountPolicy([p], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      // sum: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});
"}

