import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

// --- helpers ---
const widget: Product = { id: "w", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

function mockDiscount(fn: (s: number) => number): DiscountPolicy {
  return { computeDiscountCents: vi.fn(fn) };
}

function mockTax(fn: (t: number, r: string) => number): TaxCalculator {
  return { computeTaxCents: vi.fn(fn) };
}

function mockShipping(fn: (l: any, s: number) => number): ShippingCalculator {
  return { computeShippingCents: vi.fn(fn) };
}

// ─── Cart line management ────────────────────────────────────────────────

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("w");
    expect(snap[0]!.quantity).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(widget, 1);
    expect(cart.remove("w")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity for an existing product", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("updateQuantity(0) removes the product", () => {
    cart.add(widget, 5);
    cart.updateQuantity("w", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity rejects negative", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w", 1.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("missing", 5)).toThrow("not in the cart");
  });

  it("clear empties the cart", () => {
    cart.add(widget, 2);
    cart.add(gadget, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(widget, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Cart's internal state is unchanged
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(1000);
  });
});

// ─── Cart.totals() pricing pipeline ──────────────────────────────────────

describe("Cart.totals() pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2 * 1000 = 2000
    cart.add(gadget, 1); // 1 * 2000 = 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("returns all zeros for an empty cart", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount = mockDiscount(() => 200); // $2 off
    const tax = mockTax((taxable) => Math.floor(taxable * 0.10)); // 10%
    const shipping = mockShipping(() => 500); // $5

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(widget, 2); // subtotal = 2000

    const t = cart.totals();
    expect(t.subtotalCents).toBe(2000);
    expect(t.discountCents).toBe(200);
    // tax on discounted: (2000 - 200) * 0.10 = 180
    expect(t.taxCents).toBe(180);
    expect(t.shippingCents).toBe(500);
    // total = discountedSubtotal + tax + shipping = 1800 + 180 + 500
    expect(t.totalCents).toBe(2480);

    // Verify tax was called with discounted subtotal
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1800, "US");
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount policy returns more than subtotal
    const discount = mockDiscount(() => 99999);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discount = mockDiscount(() => -500);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax = mockTax(() => -100);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping = mockShipping(() => -50);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to US region for tax", () => {
    const tax = mockTax(() => 0);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("uses configured region for tax", () => {
    const tax = mockTax(() => 0);
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(widget, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("shipping receives discounted subtotal", () => {
    const discount = mockDiscount(() => 500);
    const shipping = mockShipping(() => 0);
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(widget, 1); // subtotal 1000, discount 500
    cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      500, // discounted subtotal
    );
  });
});

// ─── Cart.checkout() async pipeline ──────────────────────────────────────

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(widget, 2); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500), // new price
    };

    const result = await cart.checkout({ priceFetcher });
    // subtotal = 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service error");
  });

  it("checks inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w", 1);
  });

  it("throws InventoryError when product is unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("discontinued");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("w");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider to compute tax", async () => {
    const tax = mockTax(() => 0); // sync tax should be bypassed
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1); // subtotal 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // 1000 * 0.08 = 80
    expect(result.totals.taxCents).toBe(80);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    // sync tax should NOT have been called for this checkout
    expect(tax.computeTaxCents).not.toHaveBeenCalled();
  });

  it("combines priceFetcher + asyncTaxProvider + shipping", async () => {
    const discount = mockDiscount(() => 100);
    const shipping = mockShipping(() => 300);

    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(widget, 1); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
    // subtotal = 2000, discount = 100, discounted = 1900
    // tax = 1900 * 0.10 = 190, shipping = 300
    // total = 1900 + 190 + 300 = 2390
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(190);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(2390);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("inventory check runs after price refresh", async () => {
    const callOrder: string[] = [];
    const cart = new Cart();
    cart.add(widget, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("price");
        return 1000;
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("inventory");
        return { available: true };
      }),
    };

    await cart.checkout({ priceFetcher, inventoryChecker });
    expect(callOrder).toEqual(["price", "inventory"]);
  });

  it("first failing inventory line wins", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should throw");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("g");
    }
  });
});

